const http = require('http');

const send = (res, status, body, extra = {}) => {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', ...extra });
  res.end(JSON.stringify(body));
};

const server = http.createServer((req, res) => {
  if (req.url !== '/v1/users') return send(res, 404, { code: 'NOT_FOUND' });
  if (req.method !== 'POST')
    return send(res, 405, { code: 'METHOD_NOT_ALLOWED' }, { Allow: 'POST' });

  let raw = '';
  req.on('data', (c) => (raw += c));
  req.on('end', () => {
    let data;
    try {
      data = JSON.parse(raw);
    } catch {
      return send(res, 400, { code: 'INVALID_JSON' });      // 语法错 -> 400
    }
    if (!data || typeof data.name !== 'string' || !data.name.trim()) {
      return send(res, 422, { code: 'VALIDATION_FAILED' }); // 语义错 -> 422
    }
    const id = 42;
    send(res, 201, { id, name: data.name }, { Location: '/v1/users/' + id });
  });
});

server.listen(3000, () => console.log('listening on :3000'));
